#include <stdio.h>

/* teste do desafio media-ponderada — counter_protocol (03-tdd 3.9.3).
   Fase SAIDA: a captura acontece dentro do teste (freopen manda o stdout para
   um arquivo temporario proprio do cenario, fflush descarrega e o arquivo e
   lido de volta). O main e o relatorio sao do harness.
   Os valores esperados so saem com a soma entre parenteses: sem eles a
   primeira linha daria 32 e a segunda 28 — o cenario reprova. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void mediaPonderada(void);

SM_TEST(as_duas_medias_ponderadas) {
    freopen("sm_saida_1.tmp", "w", stdout);
    mediaPonderada();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("prova 10 e trabalho 5", linha, "prova 10 e trabalho 5 dao media 8\n",
              "10 vezes 3 mais 5 vezes 2 da 40, e 40 dividido por 5 da 8");
    fgets(linha, 80, f);
    checa_str("prova 9 e trabalho 4", linha, "prova 9 e trabalho 4 dao media 7\n",
              "9 vezes 3 mais 4 vezes 2 da 35, e 35 dividido por 5 da 7");
    fclose(f);
}

SM_TEST(a_saida_acaba_na_segunda_media) {
    freopen("sm_saida_2.tmp", "w", stdout);
    mediaPonderada();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    fgets(linha, 80, f);
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na segunda media: nenhuma linha extra e aceita");
    fclose(f);
}

