#include <stdio.h>

void mediaPonderada(void) {
    printf("prova 10 e trabalho 5 dao media %d\n", (10 * 3 + 5 * 2) / 5);
    printf("prova 9 e trabalho 4 dao media %d\n", (9 * 3 + 4 * 2) / 5);
}
